// Get data from SQL query
const data = items[0].json;
const webhookData = $('Webhook').first().json;

// Extract scenario parameters
const scenario_id = webhookData.body?.scenario_id || webhookData.scenario_id;
const params = webhookData.body?.parameters || webhookData.parameters;

if (!scenario_id || !params) {
    throw new Error('Missing scenario_id or parameters from orchestrator');
}

// Safe number conversion
const safeFloat = (val) => val ? parseFloat(val) : 0;

// Extract baseline values
const baselineEbitda = safeFloat(data.ebitda);
const baselineInterest = safeFloat(data.interest_expense);
const baselinePrincipal = safeFloat(data.principal_repayments);
const baselineTotalDebt = safeFloat(data.total_debt);
const baselineEbit = safeFloat(data.ebit);
const floatingDebt = safeFloat(data.total_floating_debt);
const baselineRevenue = safeFloat(data.revenue);
const baselineCogs = safeFloat(data.cogs);
const baselineOpex = safeFloat(data.operating_expenses);

// Extract parameters
const projection_horizon = params.projection_horizon || 12;
const revenue_growth_rate = params.revenue_growth_rate || 0;
const cogs_margin_change = params.cogs_margin_change || 0;
const opex_change_rate = params.opex_change_rate || 0;
const interest_rate_shock = params.interest_rate_shock || 0;
const new_debt_issuance = params.new_debt_issuance || 0;
const debt_repayment_acceleration = params.debt_repayment_acceleration || 0;

const results = [];

// Project forward
for (let month = 1; month <= projection_horizon; month++) {
    // Project revenue
    const projectedRevenue = baselineRevenue * Math.pow(
        (1 + revenue_growth_rate / 100), 
        month
    );

    // Project COGS (with margin change)
    const baselineCogsMargin = baselineRevenue > 0 ? baselineCogs / baselineRevenue : 0.6;
    const projectedCogsMargin = baselineCogsMargin + (cogs_margin_change / 100);
    const projectedCogs = projectedRevenue * projectedCogsMargin;

    // Project OPEX
    const projectedOpex = baselineOpex * Math.pow(
        (1 + opex_change_rate / 100), 
        month
    );

    // Calculate EBITDA
    const projectedEbitda = projectedRevenue - projectedCogs - projectedOpex;

    // Calculate interest (with rate shock on floating debt)
    const baseInterestRate = baselineInterest / (floatingDebt || 1);
    const shockedRate = baseInterestRate + (interest_rate_shock / 10000);
    const projectedInterest = (floatingDebt * shockedRate) + 
        ((baselineTotalDebt - floatingDebt) * baseInterestRate);

    // Calculate principal (with acceleration)
    const projectedPrincipal = baselinePrincipal * (1 + debt_repayment_acceleration / 100);

    // Calculate DSCR
    const dscr = (projectedInterest + projectedPrincipal) > 0 
        ? projectedEbitda / (projectedInterest + projectedPrincipal)
        : 999;

    // Calculate Debt to EBITDA
    const currentDebt = baselineTotalDebt + new_debt_issuance - (projectedPrincipal * month);
    const debtToEbitda = projectedEbitda > 0 ? currentDebt / projectedEbitda : 999;

    // Calculate Interest Coverage
    const interestCoverage = projectedInterest > 0 ? projectedEbitda / projectedInterest : 999;

    // Simplified Altman Z-Score (need more data for full calc)
    const altmanZ = 2.0; // Placeholder - needs full calculation

    results.push({
        scenario_id: scenario_id,
        agent_type: 'debt',
        month: month,
        metrics: {
            dscr: Number(dscr.toFixed(2)),
            debt_to_ebitda: Number(debtToEbitda.toFixed(2)),
            interest_coverage: Number(interestCoverage.toFixed(2)),
            altman_z: Number(altmanZ.toFixed(2)),
            interest_sensitivity: Number((interest_rate_shock / 100).toFixed(4))
        },
        projected_values: {
            ebitda: Number(projectedEbitda.toFixed(2)),
            interest_expense: Number(projectedInterest.toFixed(2)),
            principal_payment: Number(projectedPrincipal.toFixed(2)),
            total_debt: Number(currentDebt.toFixed(2)),
            revenue: Number(projectedRevenue.toFixed(2)),
            cogs: Number(projectedCogs.toFixed(2)),
            opex: Number(projectedOpex.toFixed(2))
        }
    });
}

return [{
    json: {
        agent_type: 'debt',
        scenario_id: scenario_id,
        results: results
    }
}];
